    {
      "assetRef": "weather_icon",
      "src": "resources/base/media/icon_weather.png",
      "use": "outdoor weather icon",
      "description": "天气语义图标，用于标识右侧室外温度信息。",
      "bindTo": "/asset/weatherIcon",
      "static": true
    },
    {
      "assetRef": "music_icon",
      "src": "resources/base/media/icon_music.png",
      "use": "music shortcut icon",
      "description": "音乐语义图标，用于跑步歌单快捷入口。",
      "bindTo": "/asset/musicIcon",
      "static": true
    },
    {
      "assetRef": "run_icon",
      "src": "resources/base/media/icon_running.png",
      "use": "running playlist icon",
      "description": "运动语义图标，用于表达跑步歌单场景。",
      "bindTo": "/asset/runIcon",
      "static": true
    }
  ]
}

